<?php require_once "../config/auth.php";requireLogin();require_once "../config/database.php";$uid=$_SESSION["user_id"];$s=$conn->prepare("SELECT e.*,c.club_name,a.status FROM event_registrations r JOIN events e ON r.event_id=e.event_id JOIN clubs c ON e.club_id=c.club_id LEFT JOIN attendance a ON a.event_id=e.event_id AND a.user_id=r.user_id WHERE r.user_id=? ORDER BY e.event_date DESC");$s->bind_param("i",$uid);$s->execute();$rows=$s->get_result();?><!DOCTYPE html><html><head><title>My Events</title><link rel="stylesheet" href="../css/style.css"></head><body><nav class="navbar"><div class="logo">Campus Clubs</div><div class="nav-links"><a href="../dashboard.php">Dashboard</a><a href="../events.php">Events</a><a href="../logout.php">Logout</a></div></nav><div class="container"><h1>My Event Registrations</h1><div class="table-wrap"><table><tr><th>Event</th><th>Club</th><th>Date</th><th>Attendance</th><th>Feedback</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=htmlspecialchars($r["event_name"])?></td><td><?=htmlspecialchars($r["club_name"])?></td><td><?=htmlspecialchars($r["event_date"])?></td><td><?=htmlspecialchars($r["status"]??"Not marked")?></td><td><a class="btn secondary" href="feedback.php?event_id=<?=$r["event_id"]?>">Feedback</a></td></tr><?php endwhile;?></table></div></div></body></html>